namespace RonSijm.FluidHumidifier.Factories.MWAAServerless;

public class WorkflowFactory(string resourceName = null, Action<Humidifier.MWAAServerless.Workflow> factoryAction = null) : ResourceFactory<Humidifier.MWAAServerless.Workflow>(resourceName)
{

    internal InnerWorkflowEncryptionConfigurationFactory EncryptionConfigurationFactory { get; set; }

    internal InnerWorkflowLoggingConfigurationFactory LoggingConfigurationFactory { get; set; }

    internal InnerWorkflowS3LocationFactory DefinitionS3LocationFactory { get; set; }

    internal InnerWorkflowNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    internal InnerWorkflowCodeFactory CodeFactory { get; set; }

    protected override Humidifier.MWAAServerless.Workflow Create()
    {
        var workflowResult = CreateWorkflow();
        factoryAction?.Invoke(workflowResult);

        return workflowResult;
    }

    private Humidifier.MWAAServerless.Workflow CreateWorkflow()
    {
        var workflowResult = new Humidifier.MWAAServerless.Workflow
        {
            GivenName = InputResourceName,
        };

        return workflowResult;
    }
    public override void CreateChildren(Humidifier.MWAAServerless.Workflow result)
    {
        base.CreateChildren(result);

        result.EncryptionConfiguration ??= EncryptionConfigurationFactory?.Build();
        result.LoggingConfiguration ??= LoggingConfigurationFactory?.Build();
        result.DefinitionS3Location ??= DefinitionS3LocationFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
        result.Code ??= CodeFactory?.Build();
    }

} // End Of Class

